int num = 0;
do {
    System.out.println(num);
    num++;
} while (num <= 10);

int n = 100;

while (n <= 10) {          // condition false immediately
    System.out.println(n); //   → body never runs
}

do {
    System.out.println(n); //   → body runs once, printing 100
} while (n <= 10);
